    int total;
    int part_size, read;

    res = &f->res[rn];
    type = res->resno;
    limits = f->res_limit + rn;
    total = n;

    if (type < 0) {
        return;
    }

    parts = res->parts;
    part_size = (total + parts - 1) / parts;
    if (part_size == 0) {
        part_size = 1;
    }

    classdata = (int *)alloca(res->classifications * sizeof(int));
    if (classdata == NULL) {
        return;
    }

    for (i = 0; i < res->classifications; i++) {
        classdata[i] = res->class[i].classdata;
    }

    for (part = 0; part < parts; part++) {
        part_end = (part + 1) * part_size;
        if (part_end > total) {
            part_end = total;
        }

        read = part_end - part * part_size;

        for (i = 0; i < read; i++) {
            for (j = 0; j < ch; j++) {
                if (!do_not_decode[j]) {
                    residue_buffers[j][part * part_size + i] = 0.0f;
                }
            }
        }

        if (type == 0) {
            decode_res0(f, residue_buffers, ch, read, part * part_size, rn, do_not_decode);
        } else if (type == 1) {
            decode_res1(f, residue_buffers, ch, read, part * part_size, rn, do_not_decode);
        }
    }
}

